  raw_url: url,
  profile_url: profileMatch ? `https://www.linkedin.com/in/${profileMatch[1]}/` : null,
  profile_slug: profileMatch?.[1] || null,
  company_slug: companyMatch?.[1] || null,
  is_profile: !!profileMatch,
  slack_user_id: body.user_id || null,
  slack_channel_id: body.channel_id || 'YOUR_SLACK_CHANNEL_ID_BRIEFS',
  slack_thread_ts: body.thread_ts || null
