={{ (() => {
  const briefRaw = $('10. Generate Brief (Claude Sonnet)').first().json.content[0].text || '{}';
  let b = {};
  try { const m = briefRaw.match(/\{[\s\S]*\}/); b = m ? JSON.parse(m[0]) : {}; } catch(e) { b = {}; }
  const profile = $('3. Apify — Scrape Profile').first().json;
  const company = $('4. Apify — Scrape Company').first().json;
  const merge = $('9d. Merge email result').first().json;
  const postsAgg = $('9.6 Posts safe').first().json || {};

  const rt = (text, bold, italic) => { const o = { type: 'text', text: { content: String(text || '') } }; if (bold || italic) o.annotations = { bold: !!bold, italic: !!italic }; return o; };
  const para = (...runs) => ({ object: 'block', type: 'paragraph', paragraph: { rich_text: runs.length ? runs : [rt('')], color: 'default' } });
  const h1 = (t) => ({ object: 'block', type: 'heading_1', heading_1: { rich_text: [rt(t)], color: 'default', is_toggleable: false } });
  const h2 = (t) => ({ object: 'block', type: 'heading_2', heading_2: { rich_text: [rt(t)], color: 'default', is_toggleable: false } });
  const bul = (...runs) => ({ object: 'block', type: 'bulleted_list_item', bulleted_list_item: { rich_text: runs, color: 'default' } });
  const num = (...runs) => ({ object: 'block', type: 'numbered_list_item', numbered_list_item: { rich_text: runs, color: 'default' } });
  const callout = (txt, emoji, color) => ({ object: 'block', type: 'callout', callout: { rich_text: [rt(txt)], icon: { type: 'emoji', emoji: emoji || '🧠' }, color: color || 'gray_background' } });
  const quote = (txt) => ({ object: 'block', type: 'quote', quote: { rich_text: [rt(txt)], color: 'default' } });
  const divider = () => ({ object: 'block', type: 'divider', divider: {} });
  const bars = (n) => '■'.repeat(Math.max(0, Math.min(5, n||0))) + '□'.repeat(5 - Math.max(0, Math.min(5, n||0)));

  const blocks = [];
  blocks.push(h1('🧠 Brief enrichi par Claude'));
  blocks.push(callout('Analyse Claude Sonnet depuis les donnees brutes Apify + posts. Email auto draft inclus.', '🧠'));

  if (b.rice) {
    blocks.push(h2('📊 RICE'));
    const axes = [['ideology','🎯','Ideology'],['ego','🪞','Ego'],['coercion','⚠️','Coercion'],['reward','💰','Reward']];
    for (const [k, em, lbl] of axes) {
      const r = b.rice[k] || {};
      const dominant = r.dominant ? ' ← DOMINANT' : '';
      blocks.push(para(rt(em + ' ' + lbl + ' ' + bars(r.score) + ' (' + (r.score||0) + '/5)' + dominant, true)));
      if (r.reason) blocks.push(para(rt(r.reason)));
    }
    if (b.rice.angle_recommande) blocks.push(para(rt('Angle recommande : ', true), rt(b.rice.angle_recommande)));
    if (b.rice.a_eviter) blocks.push(para(rt('A eviter : ', true), rt(b.rice.a_eviter)));
  }

  if (b.disc) {
    blocks.push(h2('🧠 DISC'));
    const sec = b.disc.secondary ? (' + ' + b.disc.secondary + ' (' + (b.disc.secondary_letter || '?') + ') secondaire') : '';
    blocks.push(callout((b.disc.primary || '?') + ' (' + (b.disc.primary_letter || '?') + ') dominant' + sec, '🧠'));
    if (b.disc.analysis) blocks.push(para(rt(b.disc.analysis)));
    if (b.disc.approach) blocks.push(para(rt('Approche : ', true), rt(b.disc.approach)));
  }

  if (Array.isArray(b.doors) && b.doors.length) {
    blocks.push(h2('🤝 Portes d entree rapport'));
    for (const d of b.doors) {
      blocks.push(bul(rt((d.emoji||'•') + ' ' + (d.title||'') + ' — ', true), rt(d.desc||'')));
    }
  }

  if (b.approach_plan) {
    blocks.push(h2('🎯 Approach Plan'));
    if (b.approach_plan.tag) blocks.push(callout(b.approach_plan.tag, '🎯'));
    if (Array.isArray(b.approach_plan.steps)) {
      for (const s of b.approach_plan.steps) {
        blocks.push(num(rt((s.label||'') + ' — ', true), rt(s.text||'')));
      }
    }
    if (Array.isArray(b.approach_plan.pieges) && b.approach_plan.pieges.length) {
      blocks.push(para(rt('🚫 Pieges :', true)));
      for (const p of b.approach_plan.pieges) blocks.push(bul(rt(p)));
    }
  }

  if (b.email) {
    blocks.push(h2('✏️ Draft Email T1'));
    if (b.email.objet) blocks.push(callout('Objet : ' + b.email.objet, '📩'));
    if (b.email.body) {
      const bodyLines = String(b.email.body).split('\n');
      for (const ln of bodyLines) blocks.push(quote(ln));
    }
  }

  blocks.push(divider());
  blocks.push(h2('📜 Historique'));
  const now = new Date().toISOString().replace('T',' ').slice(0,16);
  blocks.push(bul(rt(now + ' — Agent : profil + company scrapes via Apify (' + (postsAgg.post_count||0) + ' posts)')));
  blocks.push(bul(rt(now + ' — Claude Sonnet : brief enrichi (RICE: ' + (b.rice_dominant||'?') + ', DISC: ' + (b.disc_profile||'?') + ', Score: ' + (b.score||'?') + ')')));
  if (merge.email) blocks.push(bul(rt(now + ' — Email trouve via : ' + (merge.provider||'?'))));

  const properties = { Name: { title: [{ text: { content: ((profile.firstName||'') + ' ' + (profile.lastName||'')).trim() + (company.name ? ' — ' + company.name : '') } }] } };
  if (profile.linkedinUrl) properties['LinkedIn URL'] = { url: profile.linkedinUrl.toLowerCase().replace(/\/+$/, '') };
  if (profile.headline) properties['Title'] = { rich_text: [{ text: { content: profile.headline.slice(0, 2000) } }] };
  if (company.name) properties['Company'] = { rich_text: [{ text: { content: company.name } }] };
  if (merge.email) properties['Email'] = { email: merge.email };
  if (b.location) properties['Location'] = { rich_text: [{ text: { content: b.location } }] };
  if (typeof b.score === 'number') properties['Score'] = { number: b.score };
  if (b.rice_dominant) properties['RICE Dominant'] = { select: { name: b.rice_dominant } };
  if (b.disc_profile) properties['DISC Profile'] = { select: { name: b.disc_profile } };
  if (b.tier) properties['Tier'] = { select: { name: b.tier } };
  if (b.priority) properties['Priority'] = { select: { name: b.priority } };
  if (b.intent_signals) properties['Intent Signals'] = { rich_text: [{ text: { content: b.intent_signals.slice(0, 2000) } }] };
  properties['Source'] = { select: { name: 'n8n' } };
  properties['Status'] = { select: { name: '🧠 Sonnet enrichi' } };

  return JSON.stringify({
    parent: { database_id: 'YOUR_NOTION_LEADS_DATABASE_ID' },
    properties: properties,
    children: blocks.slice(0, 100)
  });
})() }}

